ALTER TABLE recruitment_attachment ADD COLUMN parse_status VARCHAR(16) NOT NULL DEFAULT 'UNPARSED' AFTER attachment_type;
ALTER TABLE recruitment_attachment ADD COLUMN parse_error VARCHAR(500) DEFAULT NULL AFTER parse_status;
ALTER TABLE recruitment_attachment ADD COLUMN parsed_at DATETIME DEFAULT NULL AFTER parse_error;
ALTER TABLE recruitment_attachment ADD COLUMN position_count INT NOT NULL DEFAULT 0 AFTER parsed_at;
CREATE TABLE recruitment_position (id BIGINT NOT NULL AUTO_INCREMENT,notice_id BIGINT NOT NULL,source_attachment_id BIGINT NOT NULL,organization_name VARCHAR(255) DEFAULT NULL,department_name VARCHAR(255) DEFAULT NULL,position_name VARCHAR(255) NOT NULL,position_code VARCHAR(128) DEFAULT NULL,recruit_count INT DEFAULT NULL,work_location VARCHAR(255) DEFAULT NULL,education_requirement VARCHAR(500) DEFAULT NULL,degree_requirement VARCHAR(500) DEFAULT NULL,major_requirement TEXT,age_requirement VARCHAR(500) DEFAULT NULL,work_years_requirement VARCHAR(500) DEFAULT NULL,responsibility TEXT,other_requirement TEXT,preferred_requirement TEXT,raw_requirement TEXT,source_sheet VARCHAR(255) NOT NULL,source_row INT NOT NULL,created_at DATETIME DEFAULT NULL,updated_at DATETIME DEFAULT NULL,PRIMARY KEY(id),UNIQUE KEY uk_recruitment_position_source(source_attachment_id,source_sheet,source_row),KEY idx_recruitment_position_notice(notice_id),CONSTRAINT fk_recruitment_position_notice FOREIGN KEY(notice_id) REFERENCES recruitment_notice(id),CONSTRAINT fk_recruitment_position_attachment FOREIGN KEY(source_attachment_id) REFERENCES recruitment_attachment(id));
CREATE TABLE recruitment_requirement (id BIGINT NOT NULL AUTO_INCREMENT,position_id BIGINT NOT NULL,requirement_type VARCHAR(32) NOT NULL,requirement_level VARCHAR(16) NOT NULL,raw_text TEXT,normalized_value VARCHAR(1000) DEFAULT NULL,source_text TEXT,created_at DATETIME DEFAULT NULL,PRIMARY KEY(id),KEY idx_recruitment_requirement_position(position_id),CONSTRAINT fk_recruitment_requirement_position FOREIGN KEY(position_id) REFERENCES recruitment_position(id) ON DELETE CASCADE);
